1	// Cold Email Engine — compliance core (Phase 1).
2	//
3	// PURE + unit-testable. This module holds NO database access and NO I/O so the
4	// same functions run identically in a server action, in the (Phase 2) send
5	// scheduler, and in test/coldemail-compliance.test.ts. Callers load the
6	// relevant rows and hand them in.
7	//
8	// It is a plain server-side module (no "use server") — import it from server
9	// actions, route handlers and the worker, never from a client bundle.
10	
11	import { createHmac, timingSafeEqual } from "node:crypto";
12	
13	// ---------------------------------------------------------------------------
14	// Shared shapes (structural — deliberately looser than the Prisma row types so
15	// callers can pass a `select`ed subset).
16	// ---------------------------------------------------------------------------
17	
18	export type SuppressionScope = "GLOBAL" | "BRAND";
19	
20	export type SuppressionLike = {
21	  email?: string | null;
22	  domain?: string | null;
23	  scope: SuppressionScope;
24	  brandId?: string | null;
25	};
26	
27	export type BrandLike = {
28	  physicalPostalAddress?: string | null;
29	  replyTo?: string | null;
30	  fromEmail?: string | null;
31	  spfVerified?: boolean;
32	  dkimVerified?: boolean;
33	  dmarcVerified?: boolean;
34	};
35	
36	/** Default per-inbox daily send ceiling (warmup-safe). Cap includes warmup. */
37	export const DEFAULT_DAILY_CAP = 40;
38	
39	// ---------------------------------------------------------------------------
40	// Normalisation
41	// ---------------------------------------------------------------------------
42	
43	/** Lower-case + trim an email. Returns "" for anything unusable. */
44	export function normalizeEmail(email: string | null | undefined): string {
45	  return (email ?? "").trim().toLowerCase();
46	}
47	
48	/** The domain part of an email, lower-cased. "" if there is no `@`. */
49	export function emailDomain(email: string | null | undefined): string {
50	  const e = normalizeEmail(email);
51	  const at = e.lastIndexOf("@");
52	  return at === -1 ? "" : e.slice(at + 1);
53	}
54	
55	// ---------------------------------------------------------------------------
56	// Suppression
57	// ---------------------------------------------------------------------------
58	
59	/**
60	 * Is `email` suppressed for the brand identified by `brandId`?
61	 *
62	 * A recipient is suppressed when ANY supplied row matches, checking BOTH the
63	 * exact address and its domain, across BOTH the GLOBAL tier and the given
64	 * brand's BRAND tier. GLOBAL always wins regardless of brand. Matching is
65	 * case-insensitive. Passing `brandId = null` checks GLOBAL rows only.
66	 */
67	export function isSuppressed(
68	  email: string,
69	  brandId: string | null,
70	  suppressions: SuppressionLike[],
71	): boolean {
72	  const addr = normalizeEmail(email);
73	  if (!addr) return false;
74	  const domain = emailDomain(addr);
75	
76	  return suppressions.some((s) => {
77	    // Scope gate: GLOBAL applies to everyone; BRAND only to its own brand.
78	    if (s.scope === "BRAND") {
79	      if (!brandId || s.brandId !== brandId) return false;
80	    }
81	    const sEmail = normalizeEmail(s.email);
82	    if (sEmail && sEmail === addr) return true;
83	    const sDomain = (s.domain ?? "").trim().toLowerCase();
84	    if (sDomain && domain && sDomain === domain) return true;
85	    return false;
86	  });
87	}
88	
89	// ---------------------------------------------------------------------------
90	// One-click unsubscribe token (RFC 8058 payload)
91	// ---------------------------------------------------------------------------
92	
93	const TOKEN_VERSION = "v1";
94	
95	/** HMAC key. AUTH_SECRET is the platform's shared signing secret. */
96	function signingKey(): string {
97	  const secret = process.env.AUTH_SECRET;
98	  if (!secret || !secret.trim()) {
99	    throw new Error("AUTH_SECRET is not set — cannot sign unsubscribe tokens");
100	  }
101	  return secret;
102	}
103	
104	function sign(payload: string): string {
105	  return createHmac("sha256", signingKey()).update(payload).digest("base64url");
106	}
107	
108	/**
109	 * A stateless, tamper-proof unsubscribe token for one contact + brand pair.
110	 * Shape: `v1.<base64url(contactId:brandId)>.<hmac>`. No DB row needed — the
111	 * endpoint verifies the signature then writes the suppression.
112	 */
113	export function unsubscribeToken(contactId: string, brandId: string): string {
114	  const body = Buffer.from(`${contactId}:${brandId}`, "utf8").toString("base64url");
115	  const payload = `${TOKEN_VERSION}.${body}`;
116	  return `${payload}.${sign(payload)}`;
117	}
118	
119	export type UnsubscribeClaims = { contactId: string; brandId: string };
120	
121	/**
122	 * Verify a token produced by `unsubscribeToken`. Returns the claims on success,
123	 * or null if the token is malformed, unknown version, or the signature does not
124	 * match. Constant-time signature comparison.
125	 */
126	export function verifyUnsubscribeToken(token: string | null | undefined): UnsubscribeClaims | null {
127	  if (!token) return null;
128	  const parts = token.split(".");
129	  if (parts.length !== 3) return null;
130	  const [version, body, mac] = parts;
131	  if (version !== TOKEN_VERSION) return null;
132	
133	  const expected = sign(`${version}.${body}`);
134	  // Constant-time compare; bail if lengths differ (timingSafeEqual throws).
135	  const a = Buffer.from(mac);
136	  const b = Buffer.from(expected);
137	  if (a.length !== b.length || !timingSafeEqual(a, b)) return null;
138	
139	  let decoded: string;
140	  try {
141	    decoded = Buffer.from(body, "base64url").toString("utf8");
142	  } catch {
143	    return null;
144	  }
145	  const sep = decoded.indexOf(":");
146	  if (sep === -1) return null;
147	  const contactId = decoded.slice(0, sep);
148	  const brandId = decoded.slice(sep + 1);
149	  if (!contactId || !brandId) return null;
150	  return { contactId, brandId };
151	}
152	
153	// ---------------------------------------------------------------------------
154	// Open / click tracking tokens (stateless, HMAC-signed, same key as unsubscribe)
155	// ---------------------------------------------------------------------------
156	
157	const OPEN_TOKEN_VERSION = "o1";
158	const CLICK_TOKEN_VERSION = "c1";
159	
160	/**
161	 * A tamper-proof open-pixel token for one send. Shape:
162	 * `o1.<base64url(sendId)>.<hmac>`. The pixel route verifies the signature then
163	 * writes an OPEN EmailEvent — no DB lookup by token is required, but the token is
164	 * also stored on the ColdSend row for auditing.
165	 */
166	export function openTrackingToken(sendId: string): string {
167	  const body = Buffer.from(sendId, "utf8").toString("base64url");
168	  const payload = `${OPEN_TOKEN_VERSION}.${body}`;
169	  return `${payload}.${sign(payload)}`;
170	}
171	
172	/** Verify an open token; returns the sendId or null. Constant-time compare. */
173	export function verifyOpenToken(token: string | null | undefined): string | null {
174	  if (!token) return null;
175	  const parts = token.split(".");
176	  if (parts.length !== 3) return null;
177	  const [version, body, mac] = parts;
178	  if (version !== OPEN_TOKEN_VERSION) return null;
179	  const a = Buffer.from(mac);
180	  const b = Buffer.from(sign(`${version}.${body}`));
181	  if (a.length !== b.length || !timingSafeEqual(a, b)) return null;
182	  try {
183	    const sendId = Buffer.from(body, "base64url").toString("utf8");
184	    return sendId || null;
185	  } catch {
186	    return null;
187	  }
188	}
189	
190	/**
191	 * A tamper-proof click-redirect token carrying the destination URL. Shape:
192	 * `c1.<base64url(sendId)>.<base64url(url)>.<hmac>`. Signing the URL is what stops
193	 * the click route becoming an open redirect: an attacker cannot swap in their own
194	 * destination without invalidating the HMAC.
195	 */
196	export function clickTrackingToken(sendId: string, url: string): string {
197	  const b1 = Buffer.from(sendId, "utf8").toString("base64url");
198	  const b2 = Buffer.from(url, "utf8").toString("base64url");
199	  const payload = `${CLICK_TOKEN_VERSION}.${b1}.${b2}`;
200	  return `${payload}.${sign(payload)}`;
201	}
202	
203	export type ClickClaims = { sendId: string; url: string };
204	
205	/** Verify a click token; returns { sendId, url } or null. Constant-time compare. */
206	export function verifyClickToken(token: string | null | undefined): ClickClaims | null {
207	  if (!token) return null;
208	  const parts = token.split(".");
209	  if (parts.length !== 4) return null;
210	  const [version, b1, b2, mac] = parts;
211	  if (version !== CLICK_TOKEN_VERSION) return null;
212	  const a = Buffer.from(mac);
213	  const b = Buffer.from(sign(`${version}.${b1}.${b2}`));
214	  if (a.length !== b.length || !timingSafeEqual(a, b)) return null;
215	  try {
216	    const sendId = Buffer.from(b1, "base64url").toString("utf8");
217	    const url = Buffer.from(b2, "base64url").toString("utf8");
218	    // Only ever redirect to absolute http(s) URLs — defence in depth on top of the
219	    // signature so a signed-but-malformed target can never drive the redirect.
220	    if (!sendId || !/^https?:\/\//i.test(url)) return null;
221	    return { sendId, url };
222	  } catch {
223	    return null;
224	  }
225	}
226	
227	// ---------------------------------------------------------------------------
228	// Sending caps
229	// ---------------------------------------------------------------------------
230	
231	/**
232	 * Would sending one more message today keep this inbox within its daily cap?
233	 * `cap <= 0` is treated as the safe default rather than "unlimited".
234	 */
235	export function dailyCapOk(sentToday: number, cap: number = DEFAULT_DAILY_CAP): boolean {
236	  const ceiling = cap > 0 ? cap : DEFAULT_DAILY_CAP;
237	  return sentToday < ceiling;
238	}
239	
240	/** Per-inbox warmup ramp: day 1 = 5, +5/day, capped at the safe ceiling. */
241	export const WARMUP_STEP = 5;
242	
243	/**
244	 * Whole days elapsed since `startedAt` (0 on the first day). `null` startedAt is
245	 * treated as day 0 — a brand with no recorded warmup start is on its first day,
246	 * never uncapped. Negative results (clock skew, future start) clamp to 0.
247	 */
248	export function warmupDayIndex(
249	  startedAt: Date | string | null | undefined,
250	  now: Date | number = Date.now(),
251	): number {
252	  if (!startedAt) return 0;
253	  const start = startedAt instanceof Date ? startedAt.getTime() : new Date(startedAt).getTime();
254	  if (!Number.isFinite(start)) return 0;
255	  const nowMs = now instanceof Date ? now.getTime() : now;
256	  const days = Math.floor((nowMs - start) / 86_400_000);
257	  return days > 0 ? days : 0;
258	}
259	
260	/**
261	 * The daily cap for an inbox on a given warmup day. `dayIndex` is 0-based (day 1
262	 * of warmup = index 0 → 5). Grows by WARMUP_STEP per day and never exceeds the
263	 * warmup-safe ceiling — the ceiling INCLUDES warmup traffic, per the deliverability
264	 * plan. A non-positive ceiling falls back to the safe default, never "unlimited".
265	 */
266	export function warmupDailyCap(dayIndex: number, ceiling: number = DEFAULT_DAILY_CAP): number {
267	  const cap = ceiling > 0 ? ceiling : DEFAULT_DAILY_CAP;
268	  const day = Number.isFinite(dayIndex) ? Math.max(0, Math.floor(dayIndex)) : 0;
269	  const ramped = WARMUP_STEP * (day + 1);
270	  return Math.min(cap, ramped);
271	}
272	
273	/**
274	 * The effective per-inbox cap for a brand right now: the warmup ramp when warmup
275	 * is enabled, otherwise the flat ceiling. `ceiling` is the brand override or the
276	 * platform default.
277	 */
278	export function effectiveDailyCap(opts: {
279	  warmupStartedAt?: Date | string | null;
280	  ceiling?: number;
281	  warmupEnabled?: boolean;
282	  now?: Date | number;
283	}): number {
284	  const ceiling = opts.ceiling && opts.ceiling > 0 ? opts.ceiling : DEFAULT_DAILY_CAP;
285	  if (opts.warmupEnabled === false) return ceiling;
286	  return warmupDailyCap(warmupDayIndex(opts.warmupStartedAt, opts.now ?? Date.now()), ceiling);
287	}
