307	// ---------------------------------------------------------------------------
308	// Transports
309	// ---------------------------------------------------------------------------
310	
311	type SmtpConfig = {
312	  host: string;
313	  port: number;
314	  user: string;
315	  pass: string;
316	  secure: boolean;
317	};
318	
319	/**
320	 * Load the platform SMTP settings the same way lib/mailer.ts does — the same
321	 * Setting rows (smtp_host/port/user/pass/secure), the same encrypted-password
322	 * tolerance, the same env fallback. Loaded lazily so importing this module never
323	 * touches the DB (keeps the module unit-testable and side-effect-free).
324	 */
325	async function loadSmtpConfig(): Promise<SmtpConfig> {
326	  const { db } = await import("@/lib/db");
327	  const { decryptSecret } = await import("@/lib/crypto-box");
328	  const rows = await db.setting.findMany({
329	    where: { key: { in: ["smtp_host", "smtp_port", "smtp_user", "smtp_pass", "smtp_secure"] } },
330	  });
331	  const s = Object.fromEntries(rows.map((r) => [r.key, r.value])) as Record<string, string>;
332	
333	  // COLD-EMAIL RELAY ISOLATION. Cold email MUST send through its own dedicated
334	  // relay (the trynxeon.com VM, its own public IP) WITHOUT dragging platform
335	  // transactional mail onto it — invoices, signups, password resets and ticket
336	  // replies ride the main mailcow (`smtp_host` = the mail VM, see lib/mailer.ts)
337	  // and their deliverability must never share a reputation pool with cold outreach.
338	  //
339	  // Before this, both engines read the ONE `smtp_host` setting, so the "isolated"
340	  // relay only ever took effect by pointing that shared setting at it — which
341	  // silently routed ALL platform mail through the cold relay too (and a single
342	  // repoint, e.g. after the relay VM was down, flipped cold email onto the main
343	  // server).
344	  //
345	  // When `COLDEMAIL_SMTP_HOST` is set, the cold path uses ONLY the `COLDEMAIL_SMTP_*`
346	  // vars — NEVER the shared platform mailbox creds, which authenticate against a
347	  // DIFFERENT server and would just fail here. An empty user means "no auth" (the
348	  // relay trusts this app host via its Postfix `mynetworks`). When it is unset the
349	  // whole block falls through to the shared platform config, so an un-migrated
350	  // deployment behaves exactly as before.
351	  const coldHost = process.env.COLDEMAIL_SMTP_HOST;
352	  if (coldHost) {
353	    return {
354	      host: coldHost,
355	      port: Number(process.env.COLDEMAIL_SMTP_PORT || 587),
356	      user: process.env.COLDEMAIL_SMTP_USER || "",
357	      pass: process.env.COLDEMAIL_SMTP_PASS || "",
358	      secure: process.env.COLDEMAIL_SMTP_SECURE === "true",
359	    };
360	  }
361	
362	  const storedPass = s.smtp_pass;
363	  const sharedPass = storedPass ? decryptSecret(storedPass) ?? storedPass : process.env.SMTP_PASS || "";
364	  return {
365	    host: s.smtp_host || process.env.SMTP_HOST || "",
366	    port: Number(s.smtp_port || process.env.SMTP_PORT || 587),
367	    user: s.smtp_user || process.env.SMTP_USER || "",
368	    pass: sharedPass,
369	    secure: (s.smtp_secure ?? process.env.SMTP_SECURE) === "true",
370	  };
371	}
372	
373	/**
374	 * Nxeon Mail (Mailcow) SMTP transport. The From identity is per-brand (passed on
375	 * each message) rather than the platform's transactional `smtp_from`, so a cold
376	 * campaign always sends as its dedicated sending identity — never as the platform.
377	 */
378	export class NxeonSmtpTransport implements MailTransport {
379	  readonly name = "nxeon-smtp";
380	  constructor(private readonly cfg: SmtpConfig) {}
381	
382	  private transporter() {
383	    if (!this.cfg.host) {
384	      return nodemailer.createTransport({ sendmail: true, newline: "unix", path: "/usr/sbin/sendmail" });
385	    }
386	    // Deliberately its own env var, NOT SMTP_TLS_SERVERNAME (that one belongs to
387	    // lib/mailer.ts's platform transactional relay, mail.nxeon.cloud). Cold email
388	    // connects to the isolated trynxeon.com relay by IP, so its cert's hostname is
389	    // different — sharing the platform's servername here made every cold-email
390	    // send fail TLS hostname verification the moment the relay got a real cert.
391	    const servername = process.env.COLDEMAIL_SMTP_TLS_SERVERNAME || undefined;
392	    return nodemailer.createTransport({
393	      host: this.cfg.host,
394	      port: this.cfg.port,
395	      secure: this.cfg.secure,
396	      auth: this.cfg.user ? { user: this.cfg.user, pass: this.cfg.pass } : undefined,
397	      // FAIL FAST — do not let one unreachable relay wedge the shared worker.
398	      // The sweep runs on the single provisioning-worker loop; nodemailer's
399	      // default has effectively no connect timeout, so when the relay VM went
400	      // down a send hung the ENTIRE worker (provisioning, billing, IP jobs) for
401	      // hours. Bounded timeouts turn that into a fast per-send failure the sweep
402	      // already handles (marks FAILED, moves on).
403	      connectionTimeout: 15_000,
404	      greetingTimeout: 10_000,
405	      socketTimeout: 30_000,
406	      ...(servername ? { tls: { servername } } : {}),
407	    });
408	  }
409	
410	  async send(msg: RenderedMessage): Promise<SendResult> {
411	    const info = await this.transporter().sendMail({
412	      from: msg.from,
413	      to: msg.to,
414	      replyTo: msg.replyTo,
415	      subject: msg.subject,
416	      html: msg.html,
417	      text: msg.text,
418	      headers: msg.headers,
419	    });
420	    return { messageId: (info as { messageId?: string })?.messageId };
421	  }
422	}
423	
424	/**
425	 * Amazon SES adapter SEAM. Left as a stub because SES is not provisioned yet and
426	 * this phase must not add dependencies or send anything. When a brand's domain
427	 * lives on SES, wire the AWS SDK here behind the same interface — the worker code
428	 * does not change.
429	 */
430	export class SesTransport implements MailTransport {
431	  readonly name = "ses";
432	  async send(_msg: RenderedMessage): Promise<SendResult> {
433	    throw new Error(
434	      "SES transport is not configured. The cold-email engine currently sends only via Nxeon Mail (SMTP). " +
435	        "Provision SES + wire the AWS SDK into SesTransport.send before selecting it.",
436	    );
437	  }
438	}
439	
440	export type TransportKind = "nxeon-smtp" | "ses";
441	
442	/**
443	 * Resolve the transport for a send. Defaults to Nxeon Mail SMTP. Async because
444	 * building the SMTP transport reads the Setting rows; kept off the module's import
445	 * path so tests can import the pure renderers without a DB.
446	 */
447	export async function getTransport(kind: TransportKind = "nxeon-smtp"): Promise<MailTransport> {
448	  if (kind === "ses") return new SesTransport();
449	  return new NxeonSmtpTransport(await loadSmtpConfig());
450	}
