1	// Cold Email Engine — send rotation + health-based auto-pause (Phase 3).
2	//
3	// PURE + unit-testable: NO database access, NO I/O. The send worker feeds it the
4	// inbox rows + today's counts and it decides (a) WHICH inbox sends the next
5	// message and (b) WHEN an inbox or a whole domain must auto-pause because its
6	// bounce/complaint rate crossed a burn threshold. Keeping this pure means the
7	// exact rotation + threshold logic the worker runs is what the tests assert.
8	//
9	// Thresholds come from research §4 and default here, but the worker sources the
10	// live values from Settings so an operator can tune them.
11	
12	// ---------------------------------------------------------------------------
13	// Rotation
14	// ---------------------------------------------------------------------------
15	
16	export type InboxStatusLike = "WARMING" | "ACTIVE" | "PAUSED" | "BURNING";
17	
18	/** The minimal inbox shape the rotation engine needs. */
19	export type RotationInbox = {
20	  id: string;
21	  status: InboxStatusLike;
22	  /** Today's allowed volume from the warmup engine (already cap-clamped). */
23	  allowedToday: number;
24	  /** Real sends already made by this inbox today. */
25	  sentToday: number;
26	  /** Domain SPF+DKIM+DMARC all verified? An inbox on an unauthenticated domain never sends. */
27	  authGreen: boolean;
28	  /** Last real send — used to spread load (least-recently-used) + honour the min gap. */
29	  lastSendAt?: Date | string | null;
30	  /** Minimum seconds between sends from this inbox (90–120 typical). */
31	  minGapSeconds?: number;
32	};
33	
34	/** Remaining sends an inbox may still make today (never negative). */
35	export function remainingCapacity(i: RotationInbox): number {
36	  return Math.max(0, Math.floor(i.allowedToday) - Math.floor(i.sentToday));
37	}
38	
39	function toMs(d: Date | string | null | undefined): number | null {
40	  if (!d) return null;
41	  const t = d instanceof Date ? d.getTime() : new Date(d).getTime();
42	  return Number.isFinite(t) ? t : null;
43	}
44	
45	/**
46	 * Is this inbox eligible to send RIGHT NOW? Requires: status ACTIVE or WARMING
47	 * (PAUSED/BURNING never send), the domain authenticated, remaining daily
48	 * capacity, and at least `minGapSeconds` elapsed since its last send.
49	 *
50	 * WARMING real bug (found live 2026-08-29, 2 days after loadBrandRotationPool
51	 * was fixed for the exact same underlying deadlock): this function's OWN
52	 * status check still hard-required ACTIVE, silently undoing that fix — the
53	 * pool correctly included a WARMING inbox, but selectNextInbox (which calls
54	 * this) rejected it anyway, so `cand` was always null and processDueSends
55	 * always `break`'d immediately. 8,740 real queued sends sat untouched for 2
56	 * days as a result. A WARMING inbox's actual send VOLUME is already kept
57	 * tiny and safe by `remainingCapacity`/`allowedToday` below (computed from
58	 * `inboxAllowedVolume()`'s ramp schedule regardless of status) — status
59	 * alone is not what makes sending safe or unsafe, capacity is. Promotion to
60	 * ACTIVE (coldEmailWarmupSweep) is judged by comparing planned vs ACTUAL
61	 * sent volume; actual volume can only ever be nonzero if a WARMING inbox is
62	 * allowed to send within its own small ramp allowance, exactly as this now
63	 * does.
64	 */
65	export function isInboxEligible(i: RotationInbox, now: Date | number = Date.now()): { eligible: boolean; reason?: string } {
66	  if (i.status !== "ACTIVE" && i.status !== "WARMING") return { eligible: false, reason: `status ${i.status}` };
67	  if (!i.authGreen) return { eligible: false, reason: "domain not authenticated (SPF/DKIM/DMARC)" };
68	  if (remainingCapacity(i) <= 0) return { eligible: false, reason: "daily cap reached" };
69	  const gap = Math.max(0, i.minGapSeconds ?? 0) * 1000;
70	  if (gap > 0) {
71	    const last = toMs(i.lastSendAt);
72	    const nowMs = now instanceof Date ? now.getTime() : now;
73	    if (last !== null && nowMs - last < gap) return { eligible: false, reason: "within min send gap" };
74	  }
75	  return { eligible: true };
76	}
77	
78	/**
79	 * Pick the next inbox to send from among a brand's inboxes: the eligible inbox
80	 * that sent least recently (spreads load, avoids clustering), tie-broken by most
81	 * remaining capacity. Returns null when none are eligible. Note `lastSendAt` here
82	 * is the PERSISTED value — the worker updates it after each send so successive
83	 * calls rotate. The min-gap check uses the same field.
84	 */
85	export function selectNextInbox(inboxes: RotationInbox[], now: Date | number = Date.now()): RotationInbox | null {
86	  const eligible = inboxes.filter((i) => isInboxEligible(i, now).eligible);
87	  if (eligible.length === 0) return null;
88	  eligible.sort((a, b) => {
89	    const la = toMs(a.lastSendAt) ?? 0;
90	    const lb = toMs(b.lastSendAt) ?? 0;
91	    if (la !== lb) return la - lb; // oldest first
92	    return remainingCapacity(b) - remainingCapacity(a); // then most headroom
93	  });
94	  return eligible[0];
95	}
96	
97	/**
98	 * Plan how to distribute `count` sends across a brand's inboxes for a sweep,
99	 * ignoring the time-gap (the worker throttles between sends) but honouring each
100	 * inbox's remaining capacity. Round-robin by remaining capacity so no single
101	 * inbox is drained first. Returns an ordered list of inbox ids (length ≤ count).
102	 * Pure — used by the worker and asserted by tests.
103	 */
104	export function planRotation(inboxes: RotationInbox[], count: number): string[] {
105	  const budget: Record<string, number> = {};
106	  const pool = inboxes.filter((i) => i.status === "ACTIVE" && i.authGreen);
107	  for (const i of pool) budget[i.id] = remainingCapacity(i);
108	  const order: string[] = [];
109	  let remaining = Math.max(0, Math.floor(count));
110	  while (remaining > 0) {
111	    // Pick the inbox with the most remaining budget this round.
112	    let best: string | null = null;
113	    for (const id of Object.keys(budget)) {
114	      if (budget[id] <= 0) continue;
115	      if (best === null || budget[id] > budget[best]) best = id;
116	    }
117	    if (best === null) break; // no capacity anywhere
118	    order.push(best);
119	    budget[best] -= 1;
120	    remaining -= 1;
121	  }
122	  return order;
123	}
124	
125	// ---------------------------------------------------------------------------
126	// Auto-pause thresholds (research §4)
127	// ---------------------------------------------------------------------------
128	
129	export type BurnThresholds = {
130	  /** Pause a single INBOX at/above this bounce rate (per inbox/day). */
131	  bouncePauseInbox: number;
132	  /** Pause the whole DOMAIN when bounce stays at/above this. */
133	  bouncePauseDomain: number;
134	  /** Hard stop + require re-verification at/above this bounce rate. */
135	  bounceHardStop: number;
136	  /** Warn (amber) at/above this bounce rate. */
137	  bounceWarn: number;
138	  /** Pause the whole DOMAIN at/above this complaint rate + flag targeting. */
139	  complaintPauseDomain: number;
140	  /** Warn (amber) at/above this complaint rate. */
141	  complaintWarn: number;
142	};
143	
144	/** Defaults straight from research §4 (auto-pause slightly under the hard ceilings). */
145	export const DEFAULT_THRESHOLDS: BurnThresholds = {
146	  bouncePauseInbox: 0.018, // 1.8%
147	  bouncePauseDomain: 0.02, // 2% sustained
148	  bounceHardStop: 0.05, // 5%
149	  bounceWarn: 0.02, // 2%
150	  complaintPauseDomain: 0.0008, // 0.08%
151	  complaintWarn: 0.0005, // 0.05%
152	};
153	
154	/** Merge partial operator overrides onto the defaults, ignoring bad numbers. */
155	export function resolveThresholds(overrides?: Partial<BurnThresholds> | null): BurnThresholds {
156	  const out = { ...DEFAULT_THRESHOLDS };
157	  if (overrides) {
158	    for (const k of Object.keys(DEFAULT_THRESHOLDS) as (keyof BurnThresholds)[]) {
159	      const v = overrides[k];
160	      if (typeof v === "number" && Number.isFinite(v) && v > 0 && v <= 1) out[k] = v;
161	    }
162	  }
163	  return out;
164	}
165	
166	/** Sent/delivered/bounce/complaint counts over the evaluation window. */
167	export type RateStats = { sent: number; delivered: number; bounces: number; complaints: number };
168	
169	/** bounces ÷ sent (0 when nothing sent). Combines hard+soft — the caller decides which. */
170	export function bounceRate(s: RateStats): number {
171	  return s.sent > 0 ? s.bounces / s.sent : 0;
172	}
173	
174	/** complaints ÷ delivered, falling back to sent when delivered is unknown/zero. */
175	export function complaintRate(s: RateStats): number {
176	  const denom = s.delivered > 0 ? s.delivered : s.sent;
177	  return denom > 0 ? s.complaints / denom : 0;
178	}
179	
180	export type HealthLevel = "healthy" | "warning" | "danger";
181	
182	export type AutoPauseVerdict = {
183	  pause: boolean;
184	  hardStop: boolean;
185	  level: HealthLevel;
186	  reasons: string[];
187	  rules: string[];
188	};
189	
190	const pct = (n: number) => `${(n * 100).toFixed(2)}%`;
191	
192	/**
193	 * Evaluate a single INBOX for auto-pause on bounce rate. `minSends` guards against
194	 * tripping on a handful of sends where a rate is meaningless. A bounce rate at/over
195	 * `bounceHardStop` sets hardStop (pause + require re-verification).
196	 */
197	export function evaluateInboxAutoPause(
198	  stats: RateStats,
199	  thresholds: BurnThresholds = DEFAULT_THRESHOLDS,
200	  minSends = 20,
201	): AutoPauseVerdict {
202	  const rules: string[] = [];
203	  const reasons: string[] = [];
204	  if (stats.sent < minSends) return { pause: false, hardStop: false, level: "healthy", reasons, rules };
205	
206	  const br = bounceRate(stats);
207	  let level: HealthLevel = "healthy";
208	  let pause = false;
209	  let hardStop = false;
210	
211	  if (br >= thresholds.bounceHardStop) {
212	    pause = true;
213	    hardStop = true;
214	    level = "danger";
215	    rules.push("bounce_hard_stop");
216	    reasons.push(`Bounce rate ${pct(br)} ≥ hard-stop ${pct(thresholds.bounceHardStop)} — paused, re-verify the list`);
217	  } else if (br >= thresholds.bouncePauseInbox) {
218	    pause = true;
219	    level = "danger";
220	    rules.push("bounce_pause_inbox");
221	    reasons.push(`Bounce rate ${pct(br)} ≥ inbox pause ${pct(thresholds.bouncePauseInbox)} — inbox paused`);
222	  } else if (br >= thresholds.bounceWarn) {
223	    level = "warning";
224	    rules.push("bounce_warn");
225	    reasons.push(`Bounce rate ${pct(br)} approaching the ceiling`);
226	  }
227	  return { pause, hardStop, level, reasons, rules };
228	}
229	
230	/**
231	 * Evaluate a whole DOMAIN for auto-pause on bounce AND complaint rate. A domain
232	 * pauses when its aggregate bounce is sustained over the domain threshold or its
233	 * complaint rate crosses the pause line (wrong ICP / deceptive copy) — because a
234	 * single burned domain poisons every recipient on it.
235	 */
236	export function evaluateDomainAutoPause(
237	  stats: RateStats,
238	  thresholds: BurnThresholds = DEFAULT_THRESHOLDS,
239	  minSends = 50,
240	): AutoPauseVerdict {
241	  const rules: string[] = [];
242	  const reasons: string[] = [];
243	  if (stats.sent < minSends) return { pause: false, hardStop: false, level: "healthy", reasons, rules };
244	
245	  const br = bounceRate(stats);
246	  const cr = complaintRate(stats);
247	  let level: HealthLevel = "healthy";
248	  let pause = false;
249	  let hardStop = false;
250	
251	  if (br >= thresholds.bounceHardStop) {
252	    pause = true;
253	    hardStop = true;
254	    level = "danger";
255	    rules.push("bounce_hard_stop");
256	    reasons.push(`Domain bounce ${pct(br)} ≥ hard-stop ${pct(thresholds.bounceHardStop)} — domain stopped, re-verify`);
257	  } else if (br >= thresholds.bouncePauseDomain) {
258	    pause = true;
259	    level = "danger";
260	    rules.push("bounce_pause_domain");
261	    reasons.push(`Domain bounce ${pct(br)} ≥ domain pause ${pct(thresholds.bouncePauseDomain)} — domain paused`);
262	  }
263	
264	  if (cr >= thresholds.complaintPauseDomain) {
265	    pause = true;
266	    level = "danger";
267	    rules.push("complaint_pause_domain");
268	    reasons.push(`Complaint rate ${pct(cr)} ≥ ${pct(thresholds.complaintPauseDomain)} — domain paused, review targeting`);
269	  } else if (cr >= thresholds.complaintWarn && level === "healthy") {
270	    level = "warning";
271	    rules.push("complaint_warn");
272	    reasons.push(`Complaint rate ${pct(cr)} approaching the ceiling`);
273	  }
274	
275	  if (level === "healthy" && br >= thresholds.bounceWarn) {
276	    level = "warning";
277	    rules.push("bounce_warn");
278	  }
279	  return { pause, hardStop, level, reasons, rules };
280	}
