274	/**
275	 * Process due sends for one eligible campaign. Returns the number actually sent so
276	 * the caller can respect the per-sweep budget across campaigns.
277	 */
278	async function processDueSends(
279	  campaign: CampaignForSend,
280	  identity: SendIdentity,
281	  ctx: {
282	    now: Date;
283	    transport: MailTransport;
284	    ceiling: number;
285	    warmupEnabled: boolean;
286	    footerDisclosure: string;
287	    budget: number;
288	  },
289	): Promise<number> {
290	  if (ctx.budget <= 0) return 0;
291	  if (!withinSendWindow(campaign, ctx.now)) return 0;
292	
293	  // ===== Phase 3 — rotation pool =====
294	  // If the brand has ACTIVE inboxes, distribute sends across them honouring each
295	  // inbox's warmup limit + dailyCap + min gap (rotation.selectNextInbox). Otherwise
296	  // fall back to the Phase 2 brand-level warmup cap (unchanged).
297	  const pool = await loadBrandRotationPool(campaign.brandId, identity, ctx.now);
298	  const useRotation = pool.length > 0;
299	  const poolById = new Map(pool.map((p) => [p.candidate.id, p]));
300	
301	  // Per-inbox daily cap (warmup-aware). Counts REAL sends today for the brand.
302	  const brand = await db.brand.findUnique({
303	    where: { id: campaign.brandId },
304	    select: { warmupStartedAt: true, dailySendCap: true },
305	  });
306	  const cap = effectiveDailyCap({
307	    warmupStartedAt: brand?.warmupStartedAt ?? null,
308	    ceiling: brand?.dailySendCap ?? ctx.ceiling,
309	    warmupEnabled: ctx.warmupEnabled,
310	    now: ctx.now,
311	  });
312	  let sentToday = await db.coldSend.count({
313	    where: { campaign: { brandId: campaign.brandId }, sentAt: { gte: startOfUtcDay(ctx.now) } },
314	  });
315	  if (!useRotation && sentToday >= cap) return 0;
316	
317	  // Suppression rows for this brand, loaded once (GLOBAL + this brand's BRAND tier).
318	  const suppressions: SuppressionLike[] = await db.suppression.findMany({
319	    where: { OR: [{ scope: "GLOBAL" }, { scope: "BRAND", brandId: campaign.brandId }] },
320	    select: { email: true, domain: true, scope: true, brandId: true },
321	  });
322	
323	  const due = await db.coldSend.findMany({
324	    where: {
325	      campaignId: campaign.id,
326	      status: "QUEUED",
327	      stepId: { not: null },
328	      scheduledFor: { lte: ctx.now },
329	    },
330	    orderBy: { scheduledFor: "asc" },
331	    take: ctx.budget,
332	    include: {
333	      contact: {
334	        select: {
335	          id: true,
336	          email: true,
337	          fullName: true,
338	          title: true,
339	          firstEmailedAt: true,
340	          emailStatus: true,
341	          business: { select: { name: true } },
342	        },
343	      },
344	      step: { select: { subject: true, bodyMarkdown: true } },
345	    },
346	  });
347	
348	  // Consent re-check immediately before send (GUARDRAIL #6) — same rationale as
349	  // the mailability/suppression re-checks below: scheduling and firing can be
350	  // days apart, and this is a hard requirement, not just a reporting count.
351	  const consentedContactIds = new Set(
352	    (
353	      await db.consentRecord.findMany({
354	        where: { contactId: { in: due.map((s) => s.contactId).filter((id): id is string => !!id) } },
355	        select: { contactId: true },
356	      })
357	    ).map((c) => c.contactId),
358	  );
359	
360	  let sent = 0;
361	  for (const s of due) {
362	    if (!s.step || !s.contact) continue;
363	
364	    // GUARDRAIL #4 — re-check suppression immediately before the send.
365	    if (isSuppressed(s.contact.email, campaign.brandId, suppressions)) {
366	      await db.coldSend.update({ where: { id: s.id }, data: { status: "SUPPRESSED" } });
367	      continue;
368	    }
369	
370	    // GUARDRAIL #5 — re-check mailability immediately before the send. A contact
371	    // can go DEAD (hard bounce, complaint) any time between being scheduled and its
372	    // scheduledFor firing, since steps are scheduled days in advance; scheduling-time
373	    // mailability alone is not enough.
374	    if (!isMailableStatus(s.contact.emailStatus)) {
375	      await db.coldSend.update({ where: { id: s.id }, data: { status: "SUPPRESSED" } });
376	      continue;
377	    }
378	
379	    // GUARDRAIL #6 — re-check consent immediately before the send. No documented
380	    // lawful basis, no send, regardless of how this row was queued.
381	    if (!consentedContactIds.has(s.contactId)) {
382	      await db.coldSend.update({ where: { id: s.id }, data: { status: "SUPPRESSED" } });
383	      continue;
384	    }
385	
386	    // Pick the sending inbox. Cold email must NEVER fall back to the shared
387	    // platform transport (ctx.transport / getTransport("nxeon-smtp")) — that's
388	    // the exact relay the platform's own transactional mail uses, and routing
389	    // outreach through it defeats the isolated-relay architecture entirely
390	    // (SPF misalignment on the trynxeon.com identity, reputation bleed onto
391	    // customer-facing mail). A brand with no eligible ACTIVE inbox right now —
392	    // including the default first-21-days state where every configured inbox
393	    // is still WARMING — has nothing safe to send through, so the rest stays
394	    // QUEUED for a later sweep instead. There used to be a Phase-2 fallback
395	    // here that sent via ctx.transport when no rotation pool existed; that path
396	    // is exactly what an audit found still silently defeating the isolation
397	    // fix whenever a brand's only inbox hadn't yet been promoted to ACTIVE.
398	    if (!useRotation) break;
399	    const cand = selectNextInbox(pool.map((p) => p.candidate), ctx.now);
400	    if (!cand) break; // no eligible inbox right now — leave the rest QUEUED
401	    const chosen = poolById.get(cand.id) ?? null;
402	    if (!chosen) break;
403	
404	    const sendIdentity = chosen.identity;
405	    const token = openTrackingToken(s.id);
406	    // Tracking/unsubscribe links must live on the ISOLATED sending domain, not
407	    // the platform's own appUrl() (nxeon.cloud) — buildMessage() defaults to
408	    // appUrl() when no base is given, which put nxeon.cloud in every
409	    // List-Unsubscribe header and click-tracking URL a cold-outreach recipient
410	    // saw, unmasking the "separate" brand entirely. trynxeon.com's own nginx
411	    // redirects any path (preserving it via $request_uri) straight to the real
412	    // app, so this is a real, working link that just shows the isolated
413	    // domain to the recipient instead of the protected one.
414	    const sendDomain = (sendIdentity.fromEmail ?? "").split("@")[1]?.trim();
415	    const linkBase = sendDomain ? `https://${sendDomain}` : undefined;
416	    const msg = buildMessage({
417	      identity: sendIdentity,
418	      step: s.step,
419	      contact: s.contact,
420	      sendId: s.id,
421	      base: linkBase,
422	      footerDisclosure: ctx.footerDisclosure,
423	      track: true,
424	    });
425	
426	    // Send via the CHOSEN INBOX'S OWN relay — the shared ctx.transport is never
427	    // used for cold email (see above).
428	    const pass = decryptSecret(chosen.smtp.passEnc);
429	    if (!pass) {
430	      await db.coldSend.update({ where: { id: s.id }, data: { status: "FAILED", error: "inbox has no usable SMTP password", trackingToken: token } });
431	      continue;
432	    }
433	    const transport = new NxeonSmtpTransport({ host: chosen.smtp.host, port: chosen.smtp.port, user: chosen.smtp.user, pass, secure: chosen.smtp.tls });
434	
435	    try {
436	      const res = await transport.send(msg);
437	      const sentAt = new Date();
438	      await db.coldSend.update({
439	        where: { id: s.id },
440	        data: {
441	          status: "SENT",
442	          sentAt,
443	          inboxId: chosen?.candidate.id ?? null,
444	          messageId: res.messageId ?? null,
445	          trackingToken: token,
446	          error: null,
447	          // Persist exactly what went out (post-personalization, post-tracking-
448	          // injection) so the admin "sent email preview" viewer has real content
449	          // to show instead of just the campaign-level template.
450	          subjectSent: msg.subject,
451	          bodyHtmlSent: msg.html,
452	        },
453	      });
454	      await db.emailEvent.create({ data: { sendId: s.id, type: "SENT" } });
455	      // LEAD-DB engagement counters: this contact was just emailed.
456	      await db.contact
457	        .update({
458	          where: { id: s.contact.id },
459	          data: {
460	            timesEmailed: { increment: 1 },
461	            lastEmailedAt: sentAt,
462	            lastCampaignId: campaign.id,
463	            ...(s.contact.firstEmailedAt ? {} : { firstEmailedAt: sentAt }),
464	          },
465	        })
466	        .catch(() => null);
467	      await recordDeliverability("SENT", {
468	        inboxId: chosen?.candidate.id ?? null,
469	        sendingDomainId: chosen?.sendingDomainId ?? null,
470	        campaignId: campaign.id,
471	        contactId: s.contact.id,
472	        sendId: s.id,
473	      });
474	      if (chosen) {
475	        // Advance the rotation state so successive picks rotate + honour the gap.
476	        chosen.candidate.sentToday += 1;
477	        chosen.candidate.lastSendAt = sentAt;
478	        await db.inbox.update({ where: { id: chosen.candidate.id }, data: { lastSendAt: sentAt } }).catch(() => null);
479	      }
480	      sentToday++;
481	      sent++;
482	    } catch (err) {
483	      const error = String((err as Error)?.message ?? err).slice(0, 500);
484	      await db.coldSend.update({ where: { id: s.id }, data: { status: "FAILED", error, inboxId: chosen?.candidate.id ?? null, trackingToken: token } });
485	      await db.emailEvent.create({ data: { sendId: s.id, type: "FAILED", meta: error } });
486	      await recordDeliverability("FAILED", {
487	        inboxId: chosen?.candidate.id ?? null,
488	        sendingDomainId: chosen?.sendingDomainId ?? null,
489	        campaignId: campaign.id,
490	        contactId: s.contact.id,
491	        sendId: s.id,
492	        meta: error,
493	      });
494	      await logEvent("error", "coldemail.send.fail", { campaignId: campaign.id, sendId: s.id, error });
495	    }
496	
497	    await sleep(jitter());
498	  }
499	  return sent;
500	}
