101	  // Resolve the contact's email from the signed contactId. If the contact is
102	  // gone we still succeed (nothing to suppress, but the request was valid).
103	  const contact = await db.contact.findUnique({
104	    where: { id: claims.contactId },
105	    select: { email: true },
106	  });
