export async function saveInbox(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const id = String(formData.get("id") ?? "").trim() || null;
  const sendingDomainId = String(formData.get("sendingDomainId") ?? "").trim();
  const email = normalizeEmail(String(formData.get("email") ?? ""));
  const provider = pick(PROVIDERS, formData.get("provider"), "SMTP");
  const strategy = pick(STRATEGIES, formData.get("strategy"), "STANDARD") as WarmupStrategyKey;
  const warmupMode = pick(MODES, formData.get("warmupMode"), "HYBRID");

  if (!sendingDomainId) return { error: "Pick a sending domain." };
  if (!email || !emailSchema.safeParse(email).success) return { error: "Enter a valid mailbox address." };
  const domain = await db.sendingDomain.findUnique({ where: { id: sendingDomainId }, select: { id: true } });
  if (!domain) return { error: "Sending domain not found." };

  // Warmup plan: default to the strategy preset, allow explicit overrides.
  const preset = WARMUP_PRESETS[strategy];
  const plan = normalizePlan({
    startCap: capInt(formData.get("startCap"), 1, 200, preset.startCap),
    targetCap: capInt(formData.get("targetCap"), 1, 500, preset.targetCap),
    rampDays: capInt(formData.get("rampDays"), 1, 90, preset.rampDays),
  });
  const dailyCap = capInt(formData.get("dailyCap"), 1, 500, plan.targetCap);
  const minGapSeconds = capInt(formData.get("minGapSeconds"), 30, 3600, 100);

  // ---- Overhaul Phase 1: per-mailbox SMTP + IMAP credentials ----
  //
  // Hosts/ports/users/TLS are always written. Passwords are WRITE-ONLY: a blank
  // password field leaves the stored (encrypted) value untouched, so editing an
  // inbox never wipes its creds and the plaintext is never echoed back to the form.
  // Passwords are encrypted with lib/crypto-box before they ever touch the DB.
  const smtpHost = String(formData.get("smtpHost") ?? "").trim().slice(0, 255);
  const smtpUser = String(formData.get("smtpUser") ?? "").trim().slice(0, 255);
  const smtpPassRaw = String(formData.get("smtpPass") ?? "");
  const smtpPort = capInt(formData.get("smtpPort"), 1, 65535, 587);
  const smtpTls = formData.get("smtpTls") === "on" || formData.get("smtpTls") === "true";
  const imapHost = String(formData.get("imapHost") ?? "").trim().slice(0, 255);
  const imapUser = String(formData.get("imapUser") ?? "").trim().slice(0, 255);
  const imapPassRaw = String(formData.get("imapPass") ?? "");
  const imapPort = capInt(formData.get("imapPort"), 1, 65535, 993);
  const imapTls = formData.get("imapTls") == null ? true : formData.get("imapTls") === "on" || formData.get("imapTls") === "true";

  const data = {
    sendingDomainId,
    email,
    provider,
    strategy,
    warmupMode,
    startCap: plan.startCap,
    targetCap: plan.targetCap,
    rampDays: plan.rampDays,
    dailyCap,
    minGapSeconds,
    smtpHost,
    smtpPort,
    smtpUser,
    smtpTls,
    imapHost,
    imapPort,
    imapUser,
    imapTls,
  };
  // Only overwrite an encrypted password when a new one was actually typed.
  const passData: { smtpPassEnc?: string; imapPassEnc?: string } = {};
  if (smtpPassRaw) passData.smtpPassEnc = encryptSecret(smtpPassRaw);
  if (imapPassRaw) passData.imapPassEnc = encryptSecret(imapPassRaw);

  try {
    if (id) {
      await db.inbox.update({ where: { id }, data: { ...data, ...passData } });
    } else {
      await db.inbox.create({ data: { ...data, ...passData, status: "WARMING", currentRampCap: plan.startCap } });
    }
  } catch (err) {
    await logEvent("error", "coldemail.inbox.save", { message: String(err) });
    return { error: "Could not save the inbox (is that address already registered?)." };
  }
  revalidatePath("/admin/coldemail/domains");
  revalidatePath("/admin/coldemail/warming");
  return { ok: true };
}

