1016	export async function setDomainVerification(_prev: ActionState, formData: FormData): Promise<ActionState> {
1017	  await requireArea("platform");
1018	  const id = String(formData.get("id") ?? "").trim();
1019	  if (!id) return { error: "Missing domain." };
1020	  const spfVerified = formData.get("spfVerified") === "on" || formData.get("spfVerified") === "true";
1021	  const dkimVerified = formData.get("dkimVerified") === "on" || formData.get("dkimVerified") === "true";
