1025	
1026	  const domain = await db.sendingDomain.findUnique({ where: { id }, select: { status: true, warmupStartedAt: true } });
1027	  if (!domain) return { error: "Domain not found." };
1028	
1029	  const authed = spfVerified && dkimVerified && dmarcVerified;
1030	  const nextStatus = domain.status === "PENDING" && authed ? "WARMING" : domain.status;
1031	  await db.sendingDomain.update({
1032	    where: { id },
1033	    data: {
1034	      spfVerified,
1035	      dkimVerified,
1036	      dmarcVerified,
1037	      trackingDomainVerified,
1038	      dmarcPolicy,
1039	      status: nextStatus,
1040	      lastCheckedAt: new Date(),
1041	      warmupStartedAt: authed ? domain.warmupStartedAt ?? new Date() : domain.warmupStartedAt,
1042	    },
